mapper.select:
select oper_id as operId, title, business_type as businessType, method, request_method as requestMethod, operator_type as operatorType, oper_name as operName, dept_name as deptName, oper_url as operUrl, oper_ip as operIp, oper_location as operLocation, oper_param as operParam, json_result as jsonResult, status, error_msg as errorMsg, oper_time as operTime from sys_oper_log
and title like concat('%', #{operLog.title}, '%')
and business_type = #{operLog.businessType}
and oper_name like concat('%', #{operLog.operName}, '%')
and status = #{operLog.status}
order by oper_time desc, oper_id desc
